async def main():
    db_url = os.environ.get("DATABASE_PUBLIC_URL")
    if not db_url:
        raise RuntimeError("DATABASE_PUBLIC_URL missing")

    if len(QUESTIONS) != 100 or len(set(QUESTIONS)) != 100:
        raise RuntimeError("Approved question pool must contain exactly 100 unique questions")

    conn = await asyncpg.connect(db_url)
    try:
        async with conn.transaction():
            before_active = await conn.fetchval(
                "SELECT COUNT(*) FROM icebreakers WHERE active=1"
            )

            await conn.execute("UPDATE icebreakers SET active=0")

            for question in QUESTIONS:
                await conn.execute("""
                    INSERT INTO icebreakers (text, active, created_at)
                    VALUES ($1, 1, NOW())
                    ON CONFLICT (text)
                    DO UPDATE SET active=1
                """, question)

            after_active = await conn.fetchval(
                "SELECT COUNT(*) FROM icebreakers WHERE active=1"
            )
            total_rows = await conn.fetchval(
                "SELECT COUNT(*) FROM icebreakers"
            )

            if after_active != 100:
                raise RuntimeError(
                    f"Expected 100 active icebreakers, got {after_active}"
                )

        print("ICEBREAKERS LOAD: OK")
        print("Было активных:", before_active)
        print("Стало активных:", after_active)
        print("Всего строк в таблице:", total_rows)
    finally:
        await conn.close()


if __name__ == "__main__":
    asyncio.run(main())
